from abq_authoring import *
start(2014,'Atlantic Surf',6,[5])
add('a','Illustrate what it means to be an entrepreneur with reference to Atlantic Surf.',20,'business-1-5','enterprising-skills-and-characteristics',['Illustrate three points. Apply 7 marks to each of the two stronger responses and 6 marks to the third.'],[response(i,f'Entrepreneurial point {i} · {sum(m)} marks',[('name','Point',m[0]),('explain','Theory',m[1]),('link','Separate relevant link',m[2])]) for i,m in enumerate([[3,1,3],[3,1,3],[3,1,2]],1)],[15,16])
add('b','‘For a contract to be legally enforceable certain essential elements must exist.’ Discuss this statement with reference to the rental of the premises by Shay Doherty for Atlantic Surf.',30,'business-0-12','essential-elements-of-a-contract',['Discuss four essential contract elements. Apply 8 marks to each of the two stronger responses and 7 marks to each of the other two.'],[response(i,f'Contract element {i} · {sum(m)} marks',[('name','Name',m[0]),('explain','Theory',m[1]),('link','Separate relevant link',m[2])]) for i,m in enumerate([[3,3,2],[3,3,2],[3,2,2],[3,2,2]],1)],[17,18])
add('c','Evaluate the effectiveness of the systems of management control in operation at Atlantic Surf.',30,'business-2-13','management-control-systems',['Evaluate three management control techniques or systems. The scheme awards 10 marks for each.'],[response(i,f'Control system {i}',[('name','Name',3),('explain','Theory',4),('link','Separate relevant link',2),('evaluate','Evaluation',1)]) for i in [1,2,3]],[18,19])
finish({'A':20,'B':30,'C':30},[15,16,17,18,19],'The paper has no finite printed answer pool. Entrepreneurial points, contract elements and management control systems are open examples. The scheme lists illustrative quality, credit, stock and financial control responses, but the paper does not print a closed choose-three menu; it remains one response.', ['The unequal 7/7/6 allocation in A and 8/8/7/7 in B are retained.','Each task retains its separate link requirement.','Scheme PDF pages are two greater than printed numbers.'])
